export function getInstallModel(model: string): InstallModel | undefined {
  return INSTALL_MODELS.find((entry) => entry.model === model);
}

export function installModelForSlug(slug: string): InstallModel | undefined {
  return INSTALL_MODELS.find((entry) => entry.slug === slug);
}
